class RecoverableAcceptance:
    """Version 1 recoverable acceptance vocabulary, local or remote. Providers must
    implement atomic recovery and downstream deduplication before advertising
    those guarantees. Legacy Store is not implicitly upgraded."""

    def get_history_window(self) -> HistoryWindow:
        """Obtain the logical owner and history epoch before first submission;
        creates no work."""
        raise NotImplementedError

    def submit(self, submission: Submission) -> AcceptanceResult:
        """Atomically associate authenticated request identity, arguments,
        operation and guarantees before acknowledging. Duplicate equal arguments
        recover the original receipt. No weaker provider fallback on unknown."""
        raise NotImplementedError

    def reconcile(self, identity: RequestIdentity) -> AcceptanceResult:
        """Authorized lookup at the original logical owner after lost request, lost
        reply or caller restart. A definite negative seals the identity against
        delayed submissions. Unavailable evidence gives unknown."""
        raise NotImplementedError

    def cancel_work(self, identity: RequestIdentity) -> CancellationResult:
        """Authorized explicit work cancellation. Cancelling a transport wait is
        never this operation and never relinquishes accepted work ownership."""
        raise NotImplementedError


class RecoverableAcceptanceClient(RecoverableAcceptance):
    """Calls abstraction.job/acceptance@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def get_history_window(self) -> HistoryWindow:
        _args = _RecoverableAcceptanceGetHistoryWindowArguments()
        _arguments = _service_encode(_write_oa_recoverable_acceptance_get_history_window_arguments, _args, 1)
        _service_decode(_read_oa_recoverable_acceptance_get_history_window_arguments, _arguments, 1)
        _request = _service_request("abstraction.job/acceptance@1", "GetHistoryWindow", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.job/acceptance@1", "GetHistoryWindow")
        _result = _service_decode(_read_oa_recoverable_acceptance_get_history_window_result, _payload, 1)
        return _result.value

    def submit(self, submission: Submission) -> AcceptanceResult:
        _service_check("Submission", submission)
        _args = _RecoverableAcceptanceSubmitArguments()
        _args.submission = submission
        _arguments = _service_encode(_write_oa_recoverable_acceptance_submit_arguments, _args, 1)
        _service_decode(_read_oa_recoverable_acceptance_submit_arguments, _arguments, 1)
        _request = _service_request("abstraction.job/acceptance@1", "Submit", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.job/acceptance@1", "Submit")
        _result = _service_decode(_read_oa_recoverable_acceptance_submit_result, _payload, 1)
        return _result.value

    def reconcile(self, identity: RequestIdentity) -> AcceptanceResult:
        _service_check("RequestIdentity", identity)
        _args = _RecoverableAcceptanceReconcileArguments()
        _args.identity = identity
        _arguments = _service_encode(_write_oa_recoverable_acceptance_reconcile_arguments, _args, 1)
        _service_decode(_read_oa_recoverable_acceptance_reconcile_arguments, _arguments, 1)
        _request = _service_request("abstraction.job/acceptance@1", "Reconcile", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.job/acceptance@1", "Reconcile")
        _result = _service_decode(_read_oa_recoverable_acceptance_reconcile_result, _payload, 1)
        return _result.value

    def cancel_work(self, identity: RequestIdentity) -> CancellationResult:
        _service_check("RequestIdentity", identity)
        _args = _RecoverableAcceptanceCancelWorkArguments()
        _args.identity = identity
        _arguments = _service_encode(_write_oa_recoverable_acceptance_cancel_work_arguments, _args, 1)
        _service_decode(_read_oa_recoverable_acceptance_cancel_work_arguments, _arguments, 1)
        _request = _service_request("abstraction.job/acceptance@1", "CancelWork", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.job/acceptance@1", "CancelWork")
        _result = _service_decode(_read_oa_recoverable_acceptance_cancel_work_result, _payload, 1)
        return _result.value


class OperationControl:
    """Observation and result access use the same authenticated caller scope and
    request identity as RecoverableAcceptance despite their separate service
    wire identity. Existing acceptance methods and wire contract remain
    unchanged."""

    def observe_work(self, identity: RequestIdentity) -> ObservationResult:
        """Observe in the original authenticated acceptance scope. Absent
        identities remain unsealed; may recover an already accepted journal."""
        raise NotImplementedError

    def read_result(self, identity: RequestIdentity, offset: int, max_bytes: int) -> ResultRead:
        """Read complete immutable bytes without exposing paths. Offset must be
        nonnegative; max_bytes must be in 1..65536. Data obeys ResultChunk
        bounds. Absence, failure, incomplete work and transport errors are never
        EOF. This read never seals an absent identity."""
        raise NotImplementedError


