class JobInventory:
    """Bounded own-scope inventory on the acceptance provider endpoint.
    Authorization is independent of cursor text and uses the existing native
    caller scope. Listing does not authorize cross-scope Observe/Cancel or
    expose private provider paths."""

    def list_work(self, cursor: str, limit: int) -> InventoryPage:
        """List only the authenticated acceptance scope. Empty cursor starts a
        bounded enumeration; limit is 1..64 snapshots. Opaque cursors are bound
        to this provider instance and caller. Sessions expire after 30 seconds
        idle and restart yields gap; at most 32 sessions exist. Each call scans
        at most 256 directory entries and 16MiB provider bytes, with a 512KiB
        compact-JSON snapshot accounting budget (frame encoding overhead is
        additional). Empty scan pages still advance. Repeating the latest input
        cursor with the same limit replays its page; older cursors return gap. A
        lost initial empty-cursor reply can be restarted explicitly; no global
        scan or cross-caller authority is implied. Partial reads may return
        unavailable rather than falsely complete. No subscription or retention
        protocol is supplied."""
        raise NotImplementedError


class JobInventoryClient(JobInventory):
    """Calls abstraction.job/inventory@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def list_work(self, cursor: str, limit: int) -> InventoryPage:
        _service_check("string", cursor)
        _service_check("i64", limit)
        _args = _JobInventoryListWorkArguments()
        _args.cursor = cursor
        _args.limit = limit
        _arguments = _service_encode(_write_oa_job_inventory_list_work_arguments, _args, 1)
        _service_decode(_read_oa_job_inventory_list_work_arguments, _arguments, 1)
        _request = _service_request("abstraction.job/inventory@1", "ListWork", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.job/inventory@1", "ListWork")
        _result = _service_decode(_read_oa_job_inventory_list_work_result, _payload, 1)
        return _result.value


class JobOperator:
    """Account-wide inventory and cross-scope cancellation on the acceptance
    provider endpoint, for the person acting through an operator program. A
    provider serves it only with a configured rights decision per call; without
    one every call is forbidden. A caller's own work stays on
    RecoverableAcceptance, OperationControl and JobInventory under ownership
    (JOB-A13)."""

    def list_account_work(self, cursor: str, limit: int) -> InventoryPage:
        """List accepted operations of every caller scope of this provider, under
        the same bounds, cursor, session, replay and gap rules as
        JobInventory.ListWork. A cursor is bound to the caller and to this
        account-wide listing. Each call is decided by the rule
        abstraction.job/inventory.read on abstraction.job/acceptance@1
        (JOB-A13); forbidden and unavailable pages carry no snapshots. Snapshots
        expose no provider paths and no caller scope."""
        raise NotImplementedError

    def cancel_operation(self, operation_id: str) -> OperatorCancellation:
        """Record cancellation intent on the operation with this receipt operation
        id, whichever scope accepted it. The id is 1..128 bytes of lowercase
        ASCII letters, digits and '-'. Each call is decided by the rule
        abstraction.job/acceptance.cancel on abstraction.job/acceptance@1
        (JOB-A13). The intent records the caller's scope. Observe the operation
        through its submitter or ListAccountWork for its terminal state."""
        raise NotImplementedError


